import React from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import HomeScreen from '../screens/Home/HomeScreen';
import AraNavigator from './AraNavigator';
import ClosetNavigator from './ClosetNavigator';
import OutfitsNavigator from './OutfitsNavigator';
import ChatScreen from '../screens/Chat/ChatScreen';
import { colors, radius } from '../theme/theme';

const Tab = createBottomTabNavigator();

const ICONS: Record<string, string> = {
  HomeTab: '🏠', AraTab: '✨', ClosetTab: '👗', OutfitsTab: '🧥', ChatTab: '💬',
};

// Emoji glyphs render as their own full-color image and ignore React
// Native's tabBarActiveTintColor entirely — so previously every tab
// icon looked visually identical regardless of which one was active,
// with only a faint label-color change beneath it as the sole (easy to
// miss) cue for which tab you were on. This wraps the active tab's
// icon in a filled pill and dims the inactive ones so the current tab
// is obvious at a glance, not just inferable from small text.
function TabIcon({ routeName, focused }: { routeName: string; focused: boolean }) {
  return (
    <View style={[styles.iconWrap, focused && styles.iconWrapActive]}>
      <Text style={[styles.icon, !focused && styles.iconInactive]}>{ICONS[routeName]}</Text>
    </View>
  );
}

export default function RootTabNavigator() {
  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        headerShown: false,
        tabBarActiveTintColor: colors.black,
        tabBarInactiveTintColor: colors.inkMuted,
        tabBarLabelStyle: { fontSize: 11 },
        tabBarStyle: { borderTopColor: colors.border, height: 60, paddingBottom: 8, paddingTop: 6 },
        tabBarIcon: ({ focused }) => <TabIcon routeName={route.name} focused={focused} />,
      })}
    >
      <Tab.Screen name="HomeTab" component={HomeScreen} options={{ tabBarLabel: 'Home' }} />
      <Tab.Screen name="AraTab" component={AraNavigator} options={{ tabBarLabel: 'Ara' }} />
      <Tab.Screen name="ClosetTab" component={ClosetNavigator} options={{ tabBarLabel: 'Closet' }} />
      <Tab.Screen name="OutfitsTab" component={OutfitsNavigator} options={{ tabBarLabel: 'Outfits' }} />
      <Tab.Screen name="ChatTab" component={ChatScreen} options={{ tabBarLabel: 'Chat' }} />
    </Tab.Navigator>
  );
}

const styles = StyleSheet.create({
  iconWrap: {
    width: 40, height: 28, borderRadius: radius.pill, alignItems: 'center', justifyContent: 'center',
  },
  iconWrapActive: { backgroundColor: colors.lavender },
  icon: { fontSize: 18 },
  iconInactive: { opacity: 0.45 },
});
